from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download'
script=r'''
const box=document.getElementById('CapabilityViewport-box'),content=document.getElementById('CapabilityViewport-content');let frames=[],changes=[],keys=[],child=false,fit=false,attached=true,epoch=0,lastInput=null;
function snapshot(){const b=box.getBoundingClientRect(),c=content.getBoundingClientRect();return{capturedAt:performance.now(),epoch,attached,child,fit,dpr:devicePixelRatio,offset:box.scrollLeft,top:box.scrollTop,width:b.width,height:b.height,content:{x:c.x-b.x,y:c.y-b.y,width:c.width,height:c.height},clientWidth:box.clientWidth,clientHeight:box.clientHeight,scrollWidth:box.scrollWidth,scrollHeight:box.scrollHeight,active:document.activeElement?.id||document.activeElement?.tagName,focusVisible:box.matches(':focus-visible'),outline:getComputedStyle(box).outline,lastInput,frames,changes,keys}}
function save(){const os=new URLSearchParams(location.search).get('os')==='mac'?'mac':'windows';return fetch('/evidence/preflight-capabilityviewport-'+os+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(snapshot())}).then(r=>{if(!r.ok)throw Error('Record failed')})}
if(new URLSearchParams(location.search).has('focus')){for(const button of document.querySelectorAll('.utility'))button.tabIndex=-1;const before=document.createElement('button');before.id='CapabilityViewport-before';before.textContent='Focus before viewport';before.style.cssText='position:absolute;left:600px;top:0;width:180px;height:44px';document.body.prepend(before)}
let timer;function later(){clearTimeout(timer);timer=setTimeout(save,90)}
function reset(){epoch++;frames=[];changes=[];keys=[];lastInput=null;box.scrollLeft=0;content.style.width=fit?'458px':'800px';content.replaceChildren();if(child){const b=document.createElement('button');b.id='CapabilityViewport-child';b.textContent='Required permissions';b.style.cssText='position:absolute;left:630px;top:35px;width:150px;height:44px;min-width:44px';content.append(b)}save()}
box.addEventListener('scroll',()=>{changes.push({t:performance.now(),offset:box.scrollLeft,top:box.scrollTop});later()});box.addEventListener('wheel',e=>{lastInput={type:'wheel',x:e.deltaX,y:e.deltaY,shift:e.shiftKey,trusted:e.isTrusted};later()});document.addEventListener('keydown',e=>{lastInput={type:'key',key:e.key,shift:e.shiftKey,trusted:e.isTrusted};keys.push({key:e.key,shift:e.shiftKey,trusted:e.isTrusted,active:document.activeElement?.id||document.activeElement?.tagName});later()});document.addEventListener('focusin',later);window.addEventListener('focus',later);document.addEventListener('click',later);
for(const b of document.querySelectorAll('.utility')){b.addEventListener('mousedown',e=>e.preventDefault());b.onclick=()=>{if(b.id==='CapabilityViewport-reset'){child=false;fit=false;reset()}else if(b.id==='CapabilityViewport-middle'){box.scrollLeft=100;save()}else if(b.id==='CapabilityViewport-child-toggle'){child=!child;reset()}else if(b.id==='CapabilityViewport-child-focus'){document.getElementById('CapabilityViewport-child')?.focus();save()}else if(b.id==='CapabilityViewport-fit'){fit=!fit;reset()}else if(b.id==='CapabilityViewport-mount'){attached=!attached;if(attached)document.getElementById('fixture').append(box);else box.remove();save()}else save()}}
reset();setInterval(()=>{frames.push({t:performance.now(),offset:box.scrollLeft,top:box.scrollTop});if(frames.length>180)frames.shift()},16);
'''
(o/'capabilityviewport-input.html').write_text('<!doctype html><meta charset="utf-8"><title>CapabilityViewport Input · original isolation</title><link rel="stylesheet" href="capabilityviewport-original.css"><style>#fixture{position:absolute;left:30px;top:70px;width:478px}.table-shell{border:0;border-radius:0}#CapabilityViewport-content{position:relative;height:120px;background:repeating-linear-gradient(90deg,#232428 0px,#232428 20px,#41434a 20px,#41434a 21px)}</style><div id="fixture"><div class="table-shell" id="CapabilityViewport-box"><div id="CapabilityViewport-content"></div></div></div><button class="utility" id="CapabilityViewport-reset">reset</button><button class="utility" id="CapabilityViewport-middle">middle</button><button class="utility" id="CapabilityViewport-child-toggle">child</button><button class="utility" id="CapabilityViewport-child-focus">focus child</button><button class="utility" id="CapabilityViewport-fit">fit</button><button class="utility" id="CapabilityViewport-mount">mount</button><button class="utility" id="CapabilityViewport-record">Record Viewport Input</button><script>'+script+'</script>')
print('Unique horizontal source input fixture prepared')
